#!/bin/bash
set -e

# ==============================================================
# Kavian CopyTrade v2.7 Pro - Complete Standalone All-in-One Installer
# Path: /opt/kaviancopytrade | Port: 8900
#
# Full Production Feature Set (Fresh Server or In-Place Upgrade):
#   - PostgreSQL 100% Persistent Multi-User Engine + AES-256-GCM Vault
#   - Built-in Crypto & Metals Scanner (Smart Auto Pro + 15M SMC Sniper)
#     with Direct Zero-Delay CopyTrade Bridge & Telegram Visual Signals
#   - CoinMarketCap + CoinGecko + CoinPaprika + CryptoCompare Market Cap
#     Rank (Crypto ONLY; Metals excluded from rank & exchange execution)
#   - Cross-Exchange Percentage SL/TP Auto-Recalibration & Exchange-Native
#     Proof Chart Candlesticks (Toobit, Bitunix, LBank, Bybit, BingX, OKX,
#     Bitget, KuCoin, CoinEx, Binance)
#   - Free $10,000 Paper Simulator Mode for All Newly Registered Users:
#       * Works immediately upon signup (even before Admin approval!)
#       * 1-Click Reset $10K Paper Balance when no Paper trades are open
#       * Real Exchange APIs locked cleanly until Admin approval & subscription
#   - Streamlined Bento HUD Studio Admin Panel (100% Bilingual FA/EN):
#       * Clean topbar with pulsing Support Unread Alert Pill + audio beep
#       * Users Tab: Create user, Broadcast Announcement to All Users,
#         +30D / Custom Days (+Days), Dedicated User Report Page (Sync Live
#         Balance, Open/Closed Positions, Proof Charts, Admin Force-Close),
#         Live Support Chatbox (with unread pulse & Clear Chat)
#       * Unified Console Tab: Merged Scanner + CopyTrade + Auth Live Logs
#       * Dedicated Backup Tab: Manual ZIP/JSON + Local Snapshots + Scheduled
#         Auto Telegram Full-State Disaster Recovery
#       * System Tab: Site Branding, Registration Policy, 1-Click Let's Encrypt
#         HTTPS SSL & Admin Security
#
# Usage:
#   1) Fresh Ubuntu/Debian server install OR zero-data-loss upgrade:
#      bash install_kaviancopytrade_v2_7.sh
#   2) Fresh install + immediate Domain & Free Let's Encrypt HTTPS SSL:
#      bash install_kaviancopytrade_v2_7.sh copy.yourdomain.com admin@yourdomain.com
# ==============================================================

APP_DIR="/opt/kaviancopytrade"
PORT="8900"
DOMAIN_ARG="${1:-}"
EMAIL_ARG="${2:-}"

echo "========================================================"
echo "  Kavian CopyTrade v2.7 Pro - Unified Installer"
echo "  Free Paper Mode | User Report | Live Chat | Full DR"
echo "========================================================"

echo "=== [1/7] Preparing $APP_DIR (preserving existing DB/config/SSL) ==="
systemctl stop kaviancopytrade.service 2>/dev/null || true
mkdir -p "$APP_DIR" "$APP_DIR/backups"
cd "$APP_DIR"

SCRIPT_SRC="$(readlink -f "$0" 2>/dev/null || echo "$0")"
if [ -f "$SCRIPT_SRC" ] && [ "$SCRIPT_SRC" != "$APP_DIR/install_kaviancopytrade_v2_7.sh" ]; then
    cp -f "$SCRIPT_SRC" "$APP_DIR/install_kaviancopytrade_v2_7.sh" 2>/dev/null || true
    chmod +x "$APP_DIR/install_kaviancopytrade_v2_7.sh" 2>/dev/null || true
fi

echo "=== [2/7] Installing system packages (Python, PostgreSQL, Nginx, Certbot) ==="
export DEBIAN_FRONTEND=noninteractive
apt-get update -y
apt-get install -y python3 python3-venv python3-pip curl openssl postgresql postgresql-contrib nginx certbot python3-certbot-nginx

systemctl enable postgresql
systemctl start postgresql

echo "=== [3/7] Configuring PostgreSQL database & .env Vault ==="
ENV_FILE="$APP_DIR/.env"
if [ ! -f "$ENV_FILE" ]; then
    DB_PASS=$(openssl rand -hex 20)
    SECRET_KEY=$(openssl rand -hex 32)
    MASTER_ENC_KEY=$(python3 -c "import os, base64; print(base64.urlsafe_b64encode(os.urandom(32)).decode('ascii'))")
    INIT_ADMIN_PASS="admin12345"

    sudo -u postgres psql -tc "SELECT 1 FROM pg_roles WHERE rolname='kaviancopytrade'" | grep -q 1 ||         sudo -u postgres psql -c "CREATE USER kaviancopytrade WITH PASSWORD '$DB_PASS';"
    sudo -u postgres psql -c "ALTER USER kaviancopytrade WITH PASSWORD '$DB_PASS';" >/dev/null
    sudo -u postgres psql -tc "SELECT 1 FROM pg_database WHERE datname='kaviancopytrade'" | grep -q 1 ||         sudo -u postgres psql -c "CREATE DATABASE kaviancopytrade OWNER kaviancopytrade;"
    sudo -u postgres psql -c "GRANT ALL PRIVILEGES ON DATABASE kaviancopytrade TO kaviancopytrade;" >/dev/null
    sudo -u postgres psql -d kaviancopytrade -c "GRANT ALL ON SCHEMA public TO kaviancopytrade;" >/dev/null 2>&1 || true

    cat << EOF_ENV > "$ENV_FILE"
DATABASE_URL=postgresql://kaviancopytrade:$DB_PASS@127.0.0.1:5432/kaviancopytrade
SECRET_KEY=$SECRET_KEY
MASTER_ENC_KEY=$MASTER_ENC_KEY
INIT_ADMIN_USER=admin
INIT_ADMIN_EMAIL=admin@kaviancopytrade.local
INIT_ADMIN_PASS=$INIT_ADMIN_PASS
PORT=$PORT
EOF_ENV
    chmod 600 "$ENV_FILE"
    echo "Created PostgreSQL database 'kaviancopytrade' & secured .env (chmod 600)."
else
    echo "Existing $ENV_FILE preserved (PostgreSQL credentials & AES master key intact)."
fi

echo "=== [4/7] Extracting Kavian CopyTrade v2.7 Pro core modules ==="
